import type {RouteConfig} from '@docusaurus/types';

export class TrailingSlashPolicy {
  readonly trailingSlash: ApplyTrailingSlashParams['trailingSlash'];
  readonly baseUrl: string;

  constructor(params: ApplyTrailingSlashParams) {
    this.trailingSlash = params.trailingSlash;
    this.baseUrl = params.baseUrl;
  }
}

export class RouteInspectionContext {
  readonly path: string;
  readonly exact: boolean;
  readonly strict: boolean;

  constructor(route: RouteConfig) {
    this.path = route.path;
    this.exact = !!route.exact;
    this.strict = !!route.strict;
  }
}

export function createRouteInspectionContexts(
  routes: RouteConfig[],
): RouteInspectionContext[] {
  return routes.map((route) => new RouteInspectionContext(route));
}

export const defaultBrokenLinkSlashPolicy = new TrailingSlashPolicy({
  trailingSlash: undefined,
  baseUrl: '/',
});

export {addTrailingSlash, removeTrailingSlash, applyTrailingSlash};

/** Recursively applies trailing slash config to all nested routes. */
export function applyRouteTrailingSlash<Route extends RouteConfig>(
  route: Route,
  params: ApplyTrailingSlashParams,
): Route {
  return {
    ...route,
    path: applyTrailingSlash(route.path, params),
    ...(route.routes && {
      routes: route.routes.map((subroute) =>
        applyRouteTrailingSlash(subroute, params),
      ),
    }),
  };
}

export function sortRoutes<Route extends RouteConfig>(
  routesToSort: Route[],
  baseUrl: string,
